-- No live users, commissions or payments persist: all fixtures are rolled back.
begin;
do $$
declare
 admin uuid:=gen_random_uuid(); merchant uuid:=gen_random_uuid(); buyer uuid:=gen_random_uuid(); actor uuid;
 shop uuid:=gen_random_uuid(); prod uuid; first_order uuid; second_order uuid; inv1 uuid; inv2 uuid;
 result jsonb; payload jsonb; row_data jsonb; lock_id uuid; fixture_secret text:=repeat('fixture-billing-secret-',4);
 schedule jsonb:=(select jsonb_agg(jsonb_build_object('open','00:00','close','00:00')) from generate_series(1,7));
 historical_day date:=(now() at time zone 'America/Sao_Paulo')::date-2;
begin
 foreach actor in array array[admin,merchant,buyer] loop insert into auth.users(id,email,email_confirmed_at) values(actor,actor::text||'@example.invalid',now()); end loop;
 insert into fly_delivery.accounts(id,role) values(admin,'admin'),(merchant,'merchant'),(buyer,'customer');
 insert into fly_delivery.customer_profiles(user_id,full_name,phone) values(buyer,'Cliente Faturas','31992345678');
 insert into fly_delivery.stores(id,owner_id,name,category,categories,address,active,is_open,fee,weekly_hours) values(shop,merchant,'Loja Faturas','Pizza',array['Pizza'],'Rua Loja 123',true,true,500,schedule);
 update fly_delivery.billing_config set commission_bps=null,payments_ready=true,bridge_hash=encode(extensions.digest(fixture_secret,'sha256'),'hex') where id=true;
 perform set_config('request.jwt.claim.sub',buyer::text,true);
 begin perform public.fd_api('admin_set_commission','{"commission_bps":1000}');raise exception 'Buyer can change commission'; exception when raise_exception then if sqlerrm not like 'FD:%' then raise; end if;end;
 begin perform public.fd_api('admin_customers');raise exception 'Buyer reads customer list'; exception when raise_exception then if sqlerrm not like 'FD:%' then raise; end if;end;
 begin perform public.fd_billing_backend('wrong','tick','{}');raise exception 'Backend accepts wrong credential'; exception when raise_exception then if sqlerrm not like 'FD: Acesso restrito ao servidor%' then raise; end if;end;
 perform set_config('request.jwt.claim.sub',admin::text,true);
 perform public.fd_api('admin_set_commission','{"commission_bps":1000}');
 if public.fd_api('billing_settings')->>'commission_bps'<>'1000' then raise exception 'Global rate not applied';end if;
 if not exists(select 1 from jsonb_array_elements(public.fd_api('admin_customers',jsonb_build_object('search','Cliente Faturas'))->'customers') c where c->>'id'=buyer::text) then raise exception 'Admin customers absent';end if;
 perform set_config('request.jwt.claim.sub',merchant::text,true);
 result:=public.fd_api('save_product',jsonb_build_object('store_id',shop,'name','Pizza','price',10000));prod:=(result->>'id')::uuid;
 perform set_config('request.jwt.claim.sub',buyer::text,true);
 payload:=jsonb_build_object('store_id',shop,'request_id',gen_random_uuid(),'address','Rua Cliente 10 - Centro','payment','cash_delivery','fee',500,'items',jsonb_build_array(jsonb_build_object('id',prod,'price',10000,'quantity',1)));
 result:=public.fd_api('place',payload);first_order:=(result->>'id')::uuid;
 perform set_config('request.jwt.claim.sub',merchant::text,true);
 perform public.fd_api('transition',jsonb_build_object('id',first_order,'status','preparing'));
 perform public.fd_api('transition',jsonb_build_object('id',first_order,'status','picked_up'));
 perform public.fd_api('transition',jsonb_build_object('id',first_order,'status','delivered'));
 if (select platform_fee_cents from fly_delivery.orders where id=first_order)<>1000 then raise exception 'Commission included delivery or wrong rate';end if;
 update fly_delivery.orders set completed_at=(historical_day+time '23:59') at time zone 'America/Sao_Paulo' where id=first_order;
 perform fly_delivery.close_daily_invoices(shop);perform fly_delivery.close_daily_invoices(shop);
 select id into inv1 from fly_delivery.daily_invoices where store_id=shop and invoice_date=historical_day;
 if inv1 is null or (select count(*) from fly_delivery.daily_invoices where store_id=shop)<>1 then raise exception 'Daily invoice duplicated or missing';end if;
 if (select due_at from fly_delivery.daily_invoices where id=inv1)<>((historical_day+1)+time '12:00') at time zone 'America/Sao_Paulo' then raise exception 'Wrong noon due date';end if;
 perform set_config('request.jwt.claim.sub',admin::text,true);
 if exists(select 1 from jsonb_array_elements(public.fd_api('catalog')) s where s->>'id'=shop::text) then raise exception 'Overdue invoice did not suspend shop';end if;
 perform public.fd_api('admin_set_suspension',jsonb_build_object('id',shop,'suspend',true));
 perform set_config('request.jwt.claim.sub',merchant::text,true);
 if exists(select 1 from jsonb_array_elements(public.fd_api('catalog')) s where s->>'id'=shop::text) then raise exception 'Suspended shop still in storefront';end if;
 if public.fd_api('session')->>'role'<>'merchant' then raise exception 'Suspension prevents payment access';end if;
 result:=public.fd_api('merchant_invoices');if not exists(select 1 from jsonb_array_elements(result->'invoices') i where i->>'id'=inv1::text and i->>'amount_cents'='1000') then raise exception 'Merchant invoice list wrong';end if;
 begin perform public.fd_billing_backend(fixture_secret,'acquire',jsonb_build_object('id',inv1,'actor',buyer));raise exception 'Buyer acquired merchant invoice';exception when raise_exception then if sqlerrm not like 'FD: Fatura não encontrada%' then raise;end if;end;
 row_data:=public.fd_billing_backend(fixture_secret,'acquire',jsonb_build_object('id',inv1,'actor',merchant));lock_id:=(row_data->>'checkout_lock_id')::uuid;
 begin perform public.fd_billing_backend(fixture_secret,'acquire',jsonb_build_object('id',inv1,'actor',merchant));raise exception 'Double checkout lock';exception when raise_exception then if sqlerrm not like 'FD: Pagamento sendo preparado%' then raise;end if;end;
 perform public.fd_billing_backend(fixture_secret,'save_link',jsonb_build_object('id',inv1,'lock_id',lock_id,'url','https://checkout.infinitepay.io/test'));
 begin perform public.fd_billing_backend(fixture_secret,'paid',jsonb_build_object('id',inv1,'amount',999,'transaction','fixture-1','slug','slug-1'));raise exception 'Wrong amount settled';exception when raise_exception then if sqlerrm not like 'FD: O valor confirmado%' then raise;end if;end;
 perform public.fd_billing_backend(fixture_secret,'paid',jsonb_build_object('id',inv1,'amount',1000,'transaction','fixture-1','slug','slug-1'));
 if exists(select 1 from jsonb_array_elements(public.fd_api('catalog')) s where s->>'id'=shop::text) then raise exception 'Payment bypassed administrator suspension';end if;
 perform set_config('request.jwt.claim.sub',admin::text,true);
 perform public.fd_api('admin_set_suspension',jsonb_build_object('id',shop,'suspend',false));
 if not exists(select 1 from jsonb_array_elements(public.fd_api('catalog')) s where s->>'id'=shop::text) then raise exception 'Reactivated shop did not return';end if;
 perform set_config('request.jwt.claim.sub',admin::text,true);
 perform public.fd_api('admin_set_commission','{"commission_bps":1500}');
 if (select platform_fee_cents from fly_delivery.orders where id=first_order)<>1000 then raise exception 'Rate change modified historical commission';end if;
 perform public.fd_api('admin_set_suspension',jsonb_build_object('id',shop,'suspend',true));
 if exists(select 1 from jsonb_array_elements(public.fd_api('catalog')) s where s->>'id'=shop::text) then raise exception 'Manual suspended shop still visible';end if;
 perform public.fd_api('admin_set_suspension',jsonb_build_object('id',shop,'suspend',false));
 perform set_config('request.jwt.claim.sub',buyer::text,true);
 result:=public.fd_api('place',payload||jsonb_build_object('request_id',gen_random_uuid()));second_order:=(result->>'id')::uuid;
 perform set_config('request.jwt.claim.sub',merchant::text,true);
 perform public.fd_api('transition',jsonb_build_object('id',second_order,'status','preparing'));perform public.fd_api('transition',jsonb_build_object('id',second_order,'status','picked_up'));perform public.fd_api('transition',jsonb_build_object('id',second_order,'status','delivered'));
 if (select platform_fee_cents from fly_delivery.orders where id=second_order)<>1500 then raise exception 'New rate not reflected in next sale';end if;
 if public.fd_api('merchant_invoices')->'today'->>'amount_cents'<>'1500' then raise exception 'Today preview wrong';end if;
 perform fly_delivery.close_daily_invoices(shop);if (select count(*) from fly_delivery.daily_invoices where store_id=shop)<>1 then raise exception 'Current day closed early';end if;
 update fly_delivery.orders set completed_at=(historical_day+time '22:00') at time zone 'America/Sao_Paulo' where id=second_order;
 -- Paid snapshots remain immutable, even if an administrator changes old records directly.
 perform fly_delivery.close_daily_invoices(shop);if (select amount_cents from fly_delivery.daily_invoices where id=inv1)<>1000 then raise exception 'Paid invoice mutated';end if;
 perform public.fd_billing_backend(fixture_secret,'tick','{"payments_ready":false}');
 if (select payments_ready from fly_delivery.billing_config where id=true) then raise exception 'Readiness not synced';end if;
end;
$$;
select 'Faturas: comissão global, base sem entrega, fechamento diário, vencimento, acesso, suspensão, locks e confirmação verificados' as integration;
rollback;
